import XCTest

class BlueskyLikeTest: XCTestCase {
    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testLikeFirstPost() {
        let app = XCUIApplication()
        app.launch()

        // Try to find and tap the heart icon
        // The heart button might have accessibility identifier or label
        let likeButton = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Like'")).firstMatch

        if likeButton.exists {
            likeButton.tap()
            XCTAssert(true, "Successfully tapped like button")
        } else {
            // Try alternative approach - tap at specific coordinates
            let coordinate = app.coordinate(withNormalizedOffset: CGVector(dx: 0.4, dy: 0.7))
            coordinate.tap()
        }
    }
}
EOF

