# Create a minimal Xcode test project structure
test_dir="/tmp/BlueskyUITest"
mkdir -p "$test_dir/BlueskyUITest"

cd "$test_dir"

# Create a simple swift test file
cat > BlueskyUITest/BlueskyUITest.swift << 'EOF'
import XCTest

class BlueskyUITest: XCTestCase {

    func testLikeFirstPost() throws {
        let app = XCUIApplication()
        app.launch()

        // Find and tap the like button on the first post
        // The heart icon should have a label or be identifiable
        let likeButtons = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Like' OR label CONTAINS 'Heart'"))

        if likeButtons.count > 0 {
            likeButtons.element(boundBy: 0).tap()
            sleep(1)
        } else {
            // Fallback: tap at approximate coordinates of the heart icon
            // Using normalized coordinates (0-1 range)
            let coordinate = app.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.65))
            coordinate.tap()
            sleep(1)
        }
    }
}
EOF

